"""
nVentures Sourcing Engine
--------------------------
This module wraps the proven notebook sourcing engine from nventure(2).ipynb.

The original engine is executed in an isolated namespace with:
- OpenRouter API key/model
- Tavily API key
- Google Sheets worksheets
- configurable run limits

The geographic filter remains a hard Python-level rule:
Afghanistan, Bangladesh, Bhutan, India, Maldives, Nepal, Pakistan,
Sri Lanka, Singapore.
"""

import json
from datetime import datetime, timezone

ELIGIBLE_COUNTRIES = {
    "afghanistan", "bangladesh", "bhutan", "india", "maldives",
    "nepal", "pakistan", "sri lanka", "singapore"
}

ENGINE_SOURCE = '# ============================================================================\n# CELL 9 — FINAL ROBUST SOURCING ENGINE\n# ============================================================================\n#\n# This version is intentionally self-contained.\n#\n# It:\n#   - Finds portfolio candidates\n#   - Handles OpenRouter 429 errors with retry/backoff\n#   - Uses fallback OpenRouter free models\n#   - Researches each company\n#   - Verifies headquarters\n#   - Enforces South Asia + Singapore geography in Python\n#   - Enforces B2B / early-stage / funding rules\n#   - Rejects mature / Series A+ companies\n#   - Deduplicates against Google Sheets\n#   - Deduplicates within the current run\n#   - Enriches missing important fields\n#   - Builds all 38 Google Sheet columns\n#   - WRITES ACCEPTED COMPANIES IMMEDIATELY\n#   - READS THE ROW BACK TO VERIFY THE WRITE\n#   - Continues when an individual partner/API call fails\n#\n# REQUIREMENT:\n# Run Cells 2–8 before this cell.\n#\n# ============================================================================\n\n\n# ============================================================================\n# 0. IMPORTS\n# ============================================================================\n\nimport os\nimport re\nimport json\nimport time\nimport random\nimport requests\nfrom datetime import datetime, timezone\n\n\nprint("=" * 80)\nprint("nVentures Fund II — FINAL SOURCING ENGINE")\nprint("=" * 80)\n\n\n# ============================================================================\n# 1. CONFIGURATION\n# ============================================================================\n\ntarget_companies = int(\n    globals().get(\n        "TARGET_NEW_COMPANIES",\n        25\n    )\n)\n\nmax_partners = int(\n    globals().get(\n        "MAX_PARTNERS_PER_RUN",\n        12\n    )\n)\n\nmax_candidates_per_partner = int(\n    globals().get(\n        "MAX_CANDIDATES_PER_PARTNER",\n        10\n    )\n)\n\nmax_deep_research = int(\n    globals().get(\n        "MAX_DEEP_RESEARCH_PER_RUN",\n        45\n    )\n)\n\nmax_total_funding = float(\n    globals().get(\n        "MAX_TOTAL_FUNDING_USD",\n        3_000_000\n    )\n)\n\nmax_team_size_warning = int(\n    globals().get(\n        "MAX_TEAM_SIZE_WARNING",\n        30\n    )\n)\n\ntavily_timeout = int(\n    globals().get(\n        "TAVILY_TIMEOUT",\n        60\n    )\n)\n\nopenrouter_timeout = int(\n    globals().get(\n        "OPENROUTER_TIMEOUT",\n        90\n    )\n)\n\nmax_tavily_results = int(\n    globals().get(\n        "MAX_TAVILY_RESULTS",\n        5\n    )\n)\n\nmax_research_chars = int(\n    globals().get(\n        "MAX_RESEARCH_CHARS",\n        14000\n    )\n)\n\nrequest_delay = float(\n    globals().get(\n        "REQUEST_DELAY_SECONDS",\n        1.5\n    )\n)\n\n\n# ============================================================================\n# 2. HARD GEOGRAPHIC FILTER\n# ============================================================================\n#\n# IMPORTANT:\n#\n# The AI does NOT get the final say on geography.\n#\n# Eligible:\n#   Afghanistan\n#   Bangladesh\n#   Bhutan\n#   India\n#   Maldives\n#   Nepal\n#   Pakistan\n#   Sri Lanka\n#   Singapore\n#\n# A San Francisco company with an Indian founder = REJECTED.\n# A Singapore-headquartered company = ACCEPTED.\n#\n# ============================================================================\n\nELIGIBLE_COUNTRIES = {\n    "afghanistan",\n    "bangladesh",\n    "bhutan",\n    "india",\n    "maldives",\n    "nepal",\n    "pakistan",\n    "sri lanka",\n    "singapore",\n}\n\n\nCOUNTRY_ALIASES = {\n    "india": "india",\n    "republic of india": "india",\n\n    "bangladesh": "bangladesh",\n    "people\'s republic of bangladesh": "bangladesh",\n    "peoples republic of bangladesh": "bangladesh",\n\n    "bhutan": "bhutan",\n    "kingdom of bhutan": "bhutan",\n\n    "maldives": "maldives",\n    "republic of maldives": "maldives",\n\n    "nepal": "nepal",\n    "federal democratic republic of nepal": "nepal",\n\n    "pakistan": "pakistan",\n    "islamic republic of pakistan": "pakistan",\n\n    "sri lanka": "sri lanka",\n    "democratic socialist republic of sri lanka": "sri lanka",\n\n    "afghanistan": "afghanistan",\n    "islamic republic of afghanistan": "afghanistan",\n\n    "singapore": "singapore",\n    "republic of singapore": "singapore",\n}\n\n\ndef normalize_text(value):\n    """Safely convert a value to clean text."""\n\n    if value is None:\n        return ""\n\n    if isinstance(value, list):\n        value = ", ".join(\n            str(x)\n            for x in value\n            if x is not None\n        )\n\n    elif isinstance(value, dict):\n        value = json.dumps(\n            value,\n            ensure_ascii=False\n        )\n\n    value = str(value)\n\n    value = value.replace(\n        "\\xa0",\n        " "\n    )\n\n    value = re.sub(\n        r"\\s+",\n        " ",\n        value\n    )\n\n    return value.strip()\n\n\ndef normalize_country(country):\n\n    country = normalize_text(\n        country\n    ).lower()\n\n    if not country:\n        return ""\n\n    country = re.sub(\n        r"\\s+",\n        " ",\n        country\n    ).strip()\n\n    return COUNTRY_ALIASES.get(\n        country,\n        country\n    )\n\n\ndef geography_check(record):\n\n    country = normalize_country(\n        record.get(\n            "Country",\n            ""\n        )\n    )\n\n    headquarters = normalize_text(\n        record.get(\n            "Headquarters",\n            ""\n        )\n    )\n\n    # ------------------------------------------------------------\n    # First preference: explicit Country field.\n    # ------------------------------------------------------------\n\n    if country in ELIGIBLE_COUNTRIES:\n\n        return True, country, headquarters\n\n\n    # ------------------------------------------------------------\n    # Second preference:\n    # Sometimes AI leaves Country blank but gives a clearly\n    # identifiable headquarters.\n    #\n    # We only use this when the headquarters explicitly contains\n    # one of the eligible country names.\n    # ------------------------------------------------------------\n\n    hq_lower = headquarters.lower()\n\n    for eligible in ELIGIBLE_COUNTRIES:\n\n        if eligible in hq_lower:\n\n            return True, eligible, headquarters\n\n\n    return False, country, headquarters\n\n\n# ============================================================================\n# 3. OPENROUTER MODELS\n# ============================================================================\n#\n# Free model availability changes.\n#\n# Primary model comes from Cell 3.\n# Fallbacks are used when OpenRouter returns 429 / provider errors.\n#\n# ============================================================================\n\nprimary_model = normalize_text(\n    globals().get(\n        "OPENROUTER_MODEL",\n        ""\n    )\n)\n\n\nfallback_models = [\n    primary_model,\n\n    "minimax/minimax-m3:free",\n\n    "google/gemma-4-31b-it:free",\n\n    "google/gemma-4-26b-a4b-it:free",\n\n    "z-ai/glm-5.2:free",\n\n    "nvidia/nemotron-3.5-super-120b-a12b:free",\n\n    "nvidia/nemotron-3.5-lightning:free",\n\n    "cohere/north-mini-code:free",\n]\n\n\n# Remove blanks and duplicates while preserving order.\n\nOPENROUTER_MODELS = []\n\nfor model in fallback_models:\n\n    if model and model not in OPENROUTER_MODELS:\n\n        OPENROUTER_MODELS.append(\n            model\n        )\n\n\nprint("\\nOpenRouter model order:")\n\nfor model in OPENROUTER_MODELS:\n\n    print(\n        f"  • {model}"\n    )\n\n\n# ============================================================================\n# 4. HTTP RETRY HELPER\n# ============================================================================\n\ndef http_request_with_retry(\n    method,\n    url,\n    *,\n    headers=None,\n    json_body=None,\n    timeout=90,\n    max_attempts=5,\n    label="HTTP request"\n):\n\n    last_error = None\n\n    for attempt in range(\n        1,\n        max_attempts + 1\n    ):\n\n        try:\n\n            response = requests.request(\n                method,\n                url,\n                headers=headers,\n                json=json_body,\n                timeout=timeout,\n            )\n\n\n            # ------------------------------------------------------------\n            # Success\n            # ------------------------------------------------------------\n\n            if response.status_code < 400:\n\n                return response\n\n\n            # ------------------------------------------------------------\n            # Rate limit / temporary server errors\n            # ------------------------------------------------------------\n\n            if response.status_code in {\n                429,\n                500,\n                502,\n                503,\n                504,\n            }:\n\n                retry_after = response.headers.get(\n                    "Retry-After"\n                )\n\n                if retry_after:\n\n                    try:\n\n                        wait_seconds = float(\n                            retry_after\n                        )\n\n                    except Exception:\n\n                        wait_seconds = min(\n                            60,\n                            2 ** attempt\n                        )\n\n                else:\n\n                    wait_seconds = min(\n                        60,\n                        2 ** attempt\n                    )\n\n\n                # Add small jitter.\n                wait_seconds += random.uniform(\n                    0.25,\n                    1.25\n                )\n\n\n                print(\n                    f"      {label}: HTTP "\n                    f"{response.status_code}. "\n                    f"Retrying in "\n                    f"{wait_seconds:.1f}s..."\n                )\n\n\n                last_error = RuntimeError(\n                    f"{label} returned "\n                    f"HTTP {response.status_code}"\n                )\n\n\n                time.sleep(\n                    wait_seconds\n                )\n\n                continue\n\n\n            # ------------------------------------------------------------\n            # Permanent HTTP error\n            # ------------------------------------------------------------\n\n            body_preview = response.text[:3000]\n\n            raise RuntimeError(\n                f"{label} failed with HTTP "\n                f"{response.status_code}:\\n"\n                f"{body_preview}"\n            )\n\n\n        except requests.RequestException as error:\n\n            last_error = error\n\n            wait_seconds = min(\n                60,\n                2 ** attempt\n            ) + random.uniform(\n                0.25,\n                1.25\n            )\n\n            print(\n                f"      {label}: network error. "\n                f"Retrying in "\n                f"{wait_seconds:.1f}s..."\n            )\n\n            time.sleep(\n                wait_seconds\n            )\n\n\n    raise RuntimeError(\n        f"{label} failed after "\n        f"{max_attempts} attempts: "\n        f"{last_error}"\n    )\n\n\n# ============================================================================\n# 5. ROBUST OPENROUTER CALL\n# ============================================================================\n\ndef robust_call_llm(\n    prompt,\n    max_tokens=1800\n):\n\n    if not OPENROUTER_API_KEY:\n\n        raise RuntimeError(\n            "OPENROUTER_API_KEY is missing."\n        )\n\n\n    url = (\n        "https://openrouter.ai/api/v1/"\n        "chat/completions"\n    )\n\n\n    errors = []\n\n\n    for model_index, model in enumerate(\n        OPENROUTER_MODELS\n    ):\n\n        headers = {\n            "Authorization":\n                f"Bearer {OPENROUTER_API_KEY}",\n\n            "Content-Type":\n                "application/json",\n\n            "HTTP-Referer":\n                "https://colab.research.google.com/",\n\n            "X-Title":\n                "nVentures Fund II Sourcing Assistant",\n        }\n\n\n        body = {\n            "model": model,\n\n            "messages": [\n                {\n                    "role": "user",\n                    "content": prompt,\n                }\n            ],\n\n            "temperature": 0.1,\n\n            "max_tokens": max_tokens,\n        }\n\n\n        try:\n\n            response = http_request_with_retry(\n                "POST",\n                url,\n                headers=headers,\n                json_body=body,\n                timeout=openrouter_timeout,\n                max_attempts=3,\n                label=f"OpenRouter [{model}]",\n            )\n\n\n            data = response.json()\n\n\n            if "error" in data:\n\n                error = data["error"]\n\n                code = (\n                    error.get("code")\n                    if isinstance(\n                        error,\n                        dict\n                    )\n                    else None\n                )\n\n\n                message = (\n                    error.get("message")\n                    if isinstance(\n                        error,\n                        dict\n                    )\n                    else str(error)\n                )\n\n\n                errors.append(\n                    f"{model}: "\n                    f"{code} — {message}"\n                )\n\n\n                # Try next model.\n                continue\n\n\n            choices = data.get(\n                "choices",\n                []\n            )\n\n\n            if not choices:\n\n                errors.append(\n                    f"{model}: no choices returned"\n                )\n\n                continue\n\n\n            message = choices[0].get(\n                "message",\n                {}\n            )\n\n\n            content = message.get(\n                "content",\n                ""\n            )\n\n\n            if not content:\n\n                errors.append(\n                    f"{model}: empty content"\n                )\n\n                continue\n\n\n            return content\n\n\n        except Exception as error:\n\n            errors.append(\n                f"{model}: {error}"\n            )\n\n            print(\n                f"      Model failed: "\n                f"{model}"\n            )\n\n            print(\n                f"      {error}"\n            )\n\n            continue\n\n\n    raise RuntimeError(\n        "All OpenRouter models failed.\\n"\n        + "\\n".join(\n            errors\n        )\n    )\n\n\n# ============================================================================\n# 6. SAFE JSON PARSER\n# ============================================================================\n\ndef safe_json_parse(text):\n\n    if isinstance(\n        text,\n        dict\n    ):\n\n        return text\n\n\n    if not text:\n\n        return {}\n\n\n    text = str(\n        text\n    ).strip()\n\n\n    # ------------------------------------------------------------\n    # Remove markdown code fences.\n    # ------------------------------------------------------------\n\n    text = re.sub(\n        r"^```(?:json)?\\s*",\n        "",\n        text,\n        flags=re.IGNORECASE\n    )\n\n    text = re.sub(\n        r"\\s*```$",\n        "",\n        text\n    )\n\n\n    # ------------------------------------------------------------\n    # First attempt: complete JSON.\n    # ------------------------------------------------------------\n\n    try:\n\n        result = json.loads(\n            text\n        )\n\n        if isinstance(\n            result,\n            dict\n        ):\n\n            return result\n\n    except Exception:\n\n        pass\n\n\n    # ------------------------------------------------------------\n    # Find first {...} block.\n    # ------------------------------------------------------------\n\n    start = text.find(\n        "{"\n    )\n\n    end = text.rfind(\n        "}"\n    )\n\n\n    if start >= 0 and end > start:\n\n        candidate = text[\n            start:end + 1\n        ]\n\n\n        try:\n\n            result = json.loads(\n                candidate\n            )\n\n            if isinstance(\n                result,\n                dict\n            ):\n\n                return result\n\n        except Exception:\n\n            pass\n\n\n    return {}\n\n\n# ============================================================================\n# 7. TAVILY SEARCH\n# ============================================================================\n\ndef tavily_search(\n    query,\n    *,\n    include_domains=None,\n    max_results=None\n):\n\n    if not TAVILY_API_KEY:\n\n        raise RuntimeError(\n            "TAVILY_API_KEY is missing."\n        )\n\n\n    if max_results is None:\n\n        max_results = max_tavily_results\n\n\n    url = (\n        "https://api.tavily.com/search"\n    )\n\n\n    body = {\n        "api_key": TAVILY_API_KEY,\n\n        "query": query,\n\n        "search_depth": "advanced",\n\n        "max_results": max_results,\n\n        "include_answer": False,\n\n        "include_raw_content": False,\n\n        "include_images": False,\n    }\n\n\n    if include_domains:\n\n        body[\n            "include_domains"\n        ] = include_domains\n\n\n    response = http_request_with_retry(\n        "POST",\n        url,\n        json_body=body,\n        timeout=tavily_timeout,\n        max_attempts=4,\n        label="Tavily",\n    )\n\n\n    data = response.json()\n\n\n    if "error" in data:\n\n        raise RuntimeError(\n            "Tavily error:\\n"\n            + json.dumps(\n                data["error"],\n                indent=2\n            )\n        )\n\n\n    return data\n\n\n# ============================================================================\n# 8. COMBINE TAVILY RESULTS\n# ============================================================================\n\ndef combined_raw_text(\n    search_response,\n    char_limit=None\n):\n\n    if not search_response:\n\n        return ""\n\n\n    pieces = []\n\n\n    answer = search_response.get(\n        "answer",\n        ""\n    )\n\n\n    if answer:\n\n        pieces.append(\n            str(answer)\n        )\n\n\n    results = search_response.get(\n        "results",\n        []\n    )\n\n\n    for result in results:\n\n        title = normalize_text(\n            result.get(\n                "title",\n                ""\n            )\n        )\n\n        content = normalize_text(\n            result.get(\n                "content",\n                ""\n            )\n        )\n\n        url = normalize_text(\n            result.get(\n                "url",\n                ""\n            )\n        )\n\n\n        block = (\n            f"TITLE: {title}\\n"\n            f"URL: {url}\\n"\n            f"CONTENT: {content}"\n        )\n\n\n        pieces.append(\n            block\n        )\n\n\n    text = "\\n\\n".join(\n        pieces\n    )\n\n\n    if char_limit:\n\n        return text[\n            :char_limit\n        ]\n\n\n    return text\n\n\n# ============================================================================\n# 9. HEADER NORMALIZATION / SHEET HELPERS\n# ============================================================================\n\ndef normalize_header(value):\n\n    value = normalize_text(\n        value\n    ).lower()\n\n    value = re.sub(\n        r"\\s+",\n        " ",\n        value\n    )\n\n    return value.strip()\n\n\ndef build_header_index(headers):\n\n    first_idx = {}\n\n    all_idx = {}\n\n\n    for column_number, header in enumerate(\n        headers,\n        start=1\n    ):\n\n        normalized = normalize_header(\n            header\n        )\n\n\n        if not normalized:\n\n            continue\n\n\n        all_idx.setdefault(\n            normalized,\n            []\n        ).append(\n            column_number\n        )\n\n\n        if normalized not in first_idx:\n\n            first_idx[\n                normalized\n            ] = column_number\n\n\n    return first_idx, all_idx\n\n\ndef get_col(\n    header,\n    first_idx\n):\n\n    if not header:\n\n        return None\n\n\n    return first_idx.get(\n        normalize_header(\n            header\n        )\n    )\n\n\ndef worksheet_rows_as_dicts(\n    worksheet\n):\n\n    values = worksheet.get_all_values()\n\n\n    if len(values) < 2:\n\n        return []\n\n\n    headers = values[0]\n\n\n    rows = []\n\n\n    for row in values[1:]:\n\n        padded = list(\n            row\n        ) + [\n            ""\n        ] * max(\n            0,\n            len(headers) - len(row)\n        )\n\n\n        record = {}\n\n\n        for i, header in enumerate(\n            headers\n        ):\n\n            record[\n                header\n            ] = padded[i]\n\n\n        rows.append(\n            record\n        )\n\n\n    return rows\n\n\n# ============================================================================\n# 10. COMPANY NORMALIZATION / DEDUPLICATION\n# ============================================================================\n\ndef normalize_company_name(\n    value\n):\n\n    value = normalize_text(\n        value\n    ).lower()\n\n\n    value = re.sub(\n        r"\\b(private|pvt|limited|ltd|llp|inc|incorporated|corp|corporation)\\b",\n        "",\n        value\n    )\n\n\n    value = re.sub(\n        r"[^a-z0-9]+",\n        "",\n        value\n    )\n\n\n    return value\n\n\ndef normalize_domain(\n    url\n):\n\n    url = normalize_text(\n        url\n    ).lower()\n\n\n    if not url:\n\n        return ""\n\n\n    # Remove markdown link if one slipped through.\n    match = re.search(\n        r"https?://[^)\\s]+",\n        url\n    )\n\n    if match:\n\n        url = match.group(\n            0\n        )\n\n\n    url = re.sub(\n        r"^https?://",\n        "",\n        url\n    )\n\n    url = re.sub(\n        r"^www\\.",\n        "",\n        url\n    )\n\n\n    url = url.split(\n        "/"\n    )[0]\n\n\n    url = url.split(\n        "?"\n    )[0]\n\n\n    return url.strip()\n\n\ndef normalize_linkedin(\n    url\n):\n\n    url = normalize_text(\n        url\n    ).lower()\n\n\n    if not url:\n\n        return ""\n\n\n    match = re.search(\n        r"https?://(?:www\\.)?linkedin\\.com/[^\\s)]+",\n        url\n    )\n\n\n    if match:\n\n        url = match.group(\n            0\n        )\n\n\n    url = url.rstrip(\n        "/"\n    )\n\n\n    return url\n\n\ndef build_existing_indexes(\n    worksheet\n):\n\n    values = worksheet.get_all_values()\n\n\n    indexes = {\n        "names": set(),\n        "domains": set(),\n        "linkedin": set(),\n    }\n\n\n    if not values:\n\n        return indexes\n\n\n    headers = values[0]\n\n\n    name_col = None\n    website_col = None\n    linkedin_col = None\n\n\n    for i, header in enumerate(\n        headers\n    ):\n\n        normalized = normalize_header(\n            header\n        )\n\n\n        if normalized == "company name":\n            name_col = i\n\n\n        elif normalized == "website":\n            website_col = i\n\n\n        elif normalized == "company linkedin":\n            linkedin_col = i\n\n\n    for row in values[1:]:\n\n        if name_col is not None and len(row) > name_col:\n\n            name = normalize_company_name(\n                row[name_col]\n            )\n\n            if name:\n\n                indexes[\n                    "names"\n                ].add(\n                    name\n                )\n\n\n        if website_col is not None and len(row) > website_col:\n\n            domain = normalize_domain(\n                row[website_col]\n            )\n\n            if domain:\n\n                indexes[\n                    "domains"\n                ].add(\n                    domain\n                )\n\n\n        if linkedin_col is not None and len(row) > linkedin_col:\n\n            linkedin = normalize_linkedin(\n                row[linkedin_col]\n            )\n\n            if linkedin:\n\n                indexes[\n                    "linkedin"\n                ].add(\n                    linkedin\n                )\n\n\n    return indexes\n\n\ndef company_is_existing(\n    company_name,\n    website="",\n    linkedin="",\n    indexes=None\n):\n\n    if indexes is None:\n\n        return False\n\n\n    name = normalize_company_name(\n        company_name\n    )\n\n    domain = normalize_domain(\n        website\n    )\n\n    linkedin = normalize_linkedin(\n        linkedin\n    )\n\n\n    if name and name in indexes[\n        "names"\n    ]:\n\n        return True\n\n\n    if domain and domain in indexes[\n        "domains"\n    ]:\n\n        return True\n\n\n    if linkedin and linkedin in indexes[\n        "linkedin"\n    ]:\n\n        return True\n\n\n    return False\n\n\ndef add_company_to_indexes(\n    company_name,\n    website="",\n    linkedin="",\n    indexes=None\n):\n\n    if indexes is None:\n\n        return\n\n\n    name = normalize_company_name(\n        company_name\n    )\n\n    domain = normalize_domain(\n        website\n    )\n\n    linkedin = normalize_linkedin(\n        linkedin\n    )\n\n\n    if name:\n\n        indexes[\n            "names"\n        ].add(\n            name\n        )\n\n\n    if domain:\n\n        indexes[\n            "domains"\n        ].add(\n            domain\n        )\n\n\n    if linkedin:\n\n        indexes[\n            "linkedin"\n        ].add(\n            linkedin\n        )\n\n\n# ============================================================================\n# 11. AI RECORD CLEANING\n# ============================================================================\n\ndef clean_ai_record(\n    record\n):\n\n    if not isinstance(\n        record,\n        dict\n    ):\n\n        return {}\n\n\n    cleaned = {}\n\n\n    for key, value in record.items():\n\n        key = normalize_text(\n            key\n        )\n\n\n        if value is None:\n\n            value = ""\n\n\n        elif isinstance(\n            value,\n            list\n        ):\n\n            value = ", ".join(\n                normalize_text(\n                    item\n                )\n                for item in value\n                if normalize_text(\n                    item\n                )\n            )\n\n\n        elif isinstance(\n            value,\n            dict\n        ):\n\n            value = json.dumps(\n                value,\n                ensure_ascii=False\n            )\n\n\n        else:\n\n            value = normalize_text(\n                value\n            )\n\n\n        # Convert markdown links to plain URLs.\n        markdown = re.match(\n            r"^\\[.*?\\]\\((https?://[^)]+)\\)$",\n            value\n        )\n\n\n        if markdown:\n\n            value = markdown.group(\n                1\n            )\n\n\n        cleaned[\n            key\n        ] = value\n\n\n    # ------------------------------------------------------------\n    # Aliases\n    # ------------------------------------------------------------\n\n    aliases = {\n\n        "Founded Year": [\n            "Founded Year",\n            "Founded year",\n            "Year Founded",\n            "Founded",\n        ],\n\n        "Product Description": [\n            "Product Description",\n            "Product Descriptoon",\n            "Product",\n        ],\n\n        "Unique Value Propositions": [\n            "Unique Value Propositions",\n            "Unique Value Propsotions",\n            "Value Proposition",\n            "UVP",\n        ],\n\n        "Founder Name": [\n            "Founder Name",\n            "Founder",\n            "Founders",\n        ],\n\n        "Founder LinkedIn": [\n            "Founder LinkedIn",\n            "Founder Linkedin",\n            "Founder LinkedIn URL",\n        ],\n\n        "Company LinkedIn": [\n            "Company LinkedIn",\n            "Company Linkedin",\n            "LinkedIn",\n            "LinkedIn URL",\n        ],\n\n        "Website": [\n            "Website",\n            "Company Website",\n            "Website URL",\n        ],\n\n        "Last Round": [\n            "Last Round",\n            "Latest Funding",\n            "Latest Funding Round",\n            "Last Funding Round",\n        ],\n\n        "Notable Investors": [\n            "Notable Investors",\n            "Investors",\n            "Key Investors",\n        ],\n\n        "Number of Customers": [\n            "Number of Customers",\n            "Customer Count",\n        ],\n\n        "Notable Customers": [\n            "Notable Customers",\n            "Key Customers",\n        ],\n\n        "Team Size": [\n            "Team Size",\n            "Employees",\n            "Employee Count",\n            "Number of Employees",\n        ],\n    }\n\n\n    for canonical, possible in aliases.items():\n\n        if canonical in cleaned:\n\n            continue\n\n\n        for candidate in possible:\n\n            if candidate in cleaned:\n\n                cleaned[\n                    canonical\n                ] = cleaned[\n                    candidate\n                ]\n\n                break\n\n\n    return cleaned\n\n\n# ============================================================================\n# 12. DETERMINISTIC FUNDING / MATURITY FILTER\n# ============================================================================\n\ndef parse_money_values(\n    text\n):\n\n    text = normalize_text(\n        text\n    ).lower()\n\n\n    if not text:\n\n        return []\n\n\n    values = []\n\n\n    patterns = [\n        (\n            r"\\$\\s*([\\d,.]+)\\s*(billion|bn)\\b",\n            1_000_000_000\n        ),\n\n        (\n            r"\\$\\s*([\\d,.]+)\\s*(million|mn|m)\\b",\n            1_000_000\n        ),\n\n        (\n            r"\\$\\s*([\\d,.]+)\\s*(thousand|k)\\b",\n            1_000\n        ),\n\n        (\n            r"usd\\s*([\\d,.]+)\\s*(billion|bn)\\b",\n            1_000_000_000\n        ),\n\n        (\n            r"usd\\s*([\\d,.]+)\\s*(million|mn|m)\\b",\n            1_000_000\n        ),\n\n        (\n            r"usd\\s*([\\d,.]+)\\s*(thousand|k)\\b",\n            1_000\n        ),\n    ]\n\n\n    for pattern, multiplier in patterns:\n\n        for match in re.finditer(\n            pattern,\n            text\n        ):\n\n            try:\n\n                number = float(\n                    match.group(\n                        1\n                    ).replace(\n                        ",",\n                        ""\n                    )\n                )\n\n\n                values.append(\n                    number * multiplier\n                )\n\n            except Exception:\n\n                pass\n\n\n    return values\n\n\ndef funding_check(\n    record,\n    research_text\n):\n\n    combined = " ".join(\n        [\n            normalize_text(\n                record.get(\n                    "Last Round",\n                    ""\n                )\n            ),\n\n            normalize_text(\n                record.get(\n                    "Stage",\n                    ""\n                )\n            ),\n\n            normalize_text(\n                research_text\n            ),\n        ]\n    )\n\n\n    combined_lower = combined.lower()\n\n\n    # ------------------------------------------------------------\n    # Hard maturity keywords.\n    # ------------------------------------------------------------\n\n    mature_terms = [\n        "series b",\n        "series c",\n        "series d",\n        "series e",\n        "series f",\n        "series g",\n        "series h",\n        "ipo",\n        "publicly listed",\n        "public company",\n        "late stage",\n        "growth stage",\n        "pre-ipo",\n    ]\n\n\n    for term in mature_terms:\n\n        if term in combined_lower:\n\n            return False, (\n                f"Maturity/funding evidence contains "\n                f"\'{term}\'."\n            )\n\n\n    # Series A is not automatically disallowed by the\n    # text alone if it refers to something unrelated,\n    # but for this early-stage mandate we treat explicit\n    # Series A evidence as a hard rejection.\n\n    if re.search(\n        r"\\bseries\\s+a\\b",\n        combined_lower\n    ):\n\n        return False, (\n            "Explicit Series A evidence."\n        )\n\n\n    # ------------------------------------------------------------\n    # Funding numbers.\n    # ------------------------------------------------------------\n\n    money_values = parse_money_values(\n        combined\n    )\n\n\n    if money_values:\n\n        maximum = max(\n            money_values\n        )\n\n\n        if maximum > max_total_funding:\n\n            return False, (\n                f"Funding evidence around "\n                f"${maximum:,.0f} exceeds the "\n                f"${max_total_funding:,.0f} limit."\n            )\n\n\n    return True, ""\n\n\n# ============================================================================\n# 13. MATURITY WARNING\n# ============================================================================\n\ndef maturity_flag(\n    record,\n    research_text\n):\n\n    combined = " ".join(\n        [\n            normalize_text(\n                record.get(\n                    "Stage",\n                    ""\n                )\n            ),\n\n            normalize_text(\n                record.get(\n                    "Last Round",\n                    ""\n                )\n            ),\n\n            normalize_text(\n                research_text\n            ),\n        ]\n    ).lower()\n\n\n    warnings = []\n\n\n    if "series a" in combined:\n\n        warnings.append(\n            "mentions \'Series A\'"\n        )\n\n\n    if "series b" in combined:\n\n        warnings.append(\n            "mentions \'Series B\'"\n        )\n\n\n    values = parse_money_values(\n        combined\n    )\n\n\n    if values:\n\n        maximum = max(\n            values\n        )\n\n\n        if maximum > max_total_funding:\n\n            warnings.append(\n                f"funding around "\n                f"${maximum:,.0f}"\n            )\n\n\n    if warnings:\n\n        return (\n            "Maturity check flagged: "\n            + "; ".join(\n                warnings\n            )\n            + "."\n        )\n\n\n    return ""\n\n\n# ============================================================================\n# 14. PARTNER CONTROL\n# ============================================================================\n\ndef get_control_state(\n    worksheet\n):\n\n    values = worksheet.get_all_values()\n\n\n    state = {}\n\n\n    if len(values) <= 1:\n\n        return state\n\n\n    for row in values[1:]:\n\n        if not row:\n\n            continue\n\n\n        name = normalize_text(\n            row[0]\n            if len(row) > 0\n            else ""\n        )\n\n\n        if not name:\n\n            continue\n\n\n        last_sourced = normalize_text(\n            row[1]\n            if len(row) > 1\n            else ""\n        )\n\n\n        try:\n\n            run_count = int(\n                row[2]\n                if len(row) > 2\n                else 0\n            )\n\n        except Exception:\n\n            run_count = 0\n\n\n        try:\n\n            last_added = int(\n                row[3]\n                if len(row) > 3\n                else 0\n            )\n\n        except Exception:\n\n            last_added = 0\n\n\n        state[\n            name\n        ] = {\n            "last_sourced":\n                last_sourced,\n\n            "run_count":\n                run_count,\n\n            "last_added":\n                last_added,\n        }\n\n\n    return state\n\n\ndef choose_partners(\n    partners,\n    control_state,\n    maximum\n):\n\n    eligible = []\n\n\n    for partner in partners:\n\n        name = normalize_text(\n            partner.get(\n                "Company Name",\n                ""\n            )\n        )\n\n\n        if not name:\n\n            continue\n\n\n        if globals().get(\n            "RESPECT_RELEVANCE_FLAG",\n            True\n        ):\n\n            relevance = normalize_text(\n                partner.get(\n                    "nVentures Relevance",\n                    ""\n                )\n            ).lower()\n\n\n            if relevance == "no":\n\n                continue\n\n\n        state = control_state.get(\n            name,\n            {}\n        )\n\n\n        last_sourced = normalize_text(\n            state.get(\n                "last_sourced",\n                ""\n            )\n        )\n\n\n        if not last_sourced:\n\n            timestamp = 0\n\n        else:\n\n            try:\n\n                parsed = datetime.fromisoformat(\n                    last_sourced.replace(\n                        "Z",\n                        "+00:00"\n                    )\n                )\n\n                timestamp = parsed.timestamp()\n\n            except Exception:\n\n                timestamp = 9999999999\n\n\n        eligible.append(\n            (\n                timestamp,\n                random.random(),\n                partner\n            )\n        )\n\n\n    eligible.sort(\n        key=lambda x: (\n            x[0],\n            x[1]\n        )\n    )\n\n\n    return [\n        item[2]\n        for item in eligible[:maximum]\n    ]\n\n\ndef update_control_state(\n    worksheet,\n    partner_name,\n    added_count\n):\n\n    now = datetime.now(\n        timezone.utc\n    ).isoformat()\n\n\n    values = worksheet.get_all_values()\n\n\n    existing_row = None\n    previous_runs = 0\n\n\n    for i, row in enumerate(\n        values[1:],\n        start=2\n    ):\n\n        if (\n            row\n            and normalize_text(\n                row[0]\n            ).lower()\n            ==\n            partner_name.lower()\n        ):\n\n            existing_row = i\n\n\n            try:\n\n                previous_runs = int(\n                    row[2]\n                    if len(row) > 2\n                    else 0\n                )\n\n            except Exception:\n\n                previous_runs = 0\n\n\n            break\n\n\n    new_row = [\n        partner_name,\n        now,\n        previous_runs + 1,\n        added_count,\n    ]\n\n\n    if existing_row:\n\n        worksheet.update(\n            f"A{existing_row}:D{existing_row}",\n            [new_row],\n            value_input_option="USER_ENTERED"\n        )\n\n    else:\n\n        worksheet.append_row(\n            new_row,\n            value_input_option="USER_ENTERED"\n        )\n\n\n# ============================================================================\n# 15. BUILD GOOGLE SHEETS ROW\n# ============================================================================\n\ndef build_sheet_row(\n    headers,\n    record,\n    partner_name,\n    verification,\n    maturity_note\n):\n\n    row = [\n        ""\n    ] * len(\n        headers\n    )\n\n\n    first_idx, all_idx = build_header_index(\n        headers\n    )\n\n\n    # ------------------------------------------------------------\n    # Exact field mapping.\n    # These correspond to your actual Active Sourcing headers.\n    # ------------------------------------------------------------\n\n    field_mapping = {\n\n        "Company Name":\n            "Company Name",\n\n        "Country":\n            "Country",\n\n        "Sector":\n            "Sector",\n\n        "Business Model":\n            "Business Model",\n\n        "Stage":\n            "Stage",\n\n        "Founded Year":\n            "Founded year",\n\n        "Headquarters":\n            "Headquarters",\n\n        "Website":\n            "Website",\n\n        "Company LinkedIn":\n            "Company LinkedIn",\n\n        "Company Description":\n            "Company Description",\n\n        "Product Description":\n            "Product Descriptoon",\n\n        "Target Market":\n            "Target Market",\n\n        "Team Size":\n            "Team Size",\n\n        "Number of Customers":\n            "Number of Customers",\n\n        "Notable Customers":\n            "Notable Customers",\n\n        "Revenue Generated":\n            "Revenue Generated",\n\n        "Unique Value Propositions":\n            "Unique Value Propsotions",\n\n        "Competitors":\n            "Competitors",\n\n        "Vision":\n            "Vision",\n\n        "Founder Name":\n            "Founder Name ",\n\n        "Founder LinkedIn":\n            "Founder LinkedIn",\n\n        "Last Round":\n            "Last Round",\n\n        "Notable Investors":\n            "Notable Investors",\n    }\n\n\n    populated = []\n\n\n    for field, header in field_mapping.items():\n\n        value = normalize_text(\n            record.get(\n                field,\n                ""\n            )\n        )\n\n\n        if not value:\n\n            continue\n\n\n        col = get_col(\n            header,\n            first_idx\n        )\n\n\n        if not col:\n\n            continue\n\n\n        row[\n            col - 1\n        ] = value\n\n\n        populated.append(\n            field\n        )\n\n\n    # ------------------------------------------------------------\n    # Outreach status\n    # ------------------------------------------------------------\n\n    col = get_col(\n        "Outreach status",\n        first_idx\n    )\n\n\n    if col:\n\n        row[\n            col - 1\n        ] = "Not Reached Out"\n\n\n    # ------------------------------------------------------------\n    # Status\n    # ------------------------------------------------------------\n\n    col = get_col(\n        "Status",\n        first_idx\n    )\n\n\n    if col:\n\n        row[\n            col - 1\n        ] = "Sourced"\n\n\n    # ------------------------------------------------------------\n    # IC Recommendation\n    # ------------------------------------------------------------\n\n    col = get_col(\n        "IC Recommendation",\n        first_idx\n    )\n\n\n    if col:\n\n        row[\n            col - 1\n        ] = "Potential Fit"\n\n\n    # ------------------------------------------------------------\n    # Reason\n    # ------------------------------------------------------------\n\n    reason_parts = []\n\n\n    if verification.get(\n        "b2b",\n        False\n    ):\n\n        reason_parts.append(\n            "B2B"\n        )\n\n\n    if verification.get(\n        "early_stage",\n        False\n    ):\n\n        reason_parts.append(\n            "early-stage"\n        )\n\n\n    if verification.get(\n        "funding_within_limit",\n        False\n    ):\n\n        reason_parts.append(\n            "funding within threshold"\n        )\n\n\n    verification_reason = normalize_text(\n        verification.get(\n            "reason",\n            ""\n        )\n    )\n\n\n    if verification_reason:\n\n        reason_parts.append(\n            verification_reason\n        )\n\n\n    reason = "; ".join(\n        reason_parts\n    )\n\n\n    col = get_col(\n        "Reason",\n        first_idx\n    )\n\n\n    if col:\n\n        row[\n            col - 1\n        ] = reason\n\n\n    # ------------------------------------------------------------\n    # Extra Notes\n    # ------------------------------------------------------------\n\n    note = (\n        f"Sourced via {partner_name}. "\n        f"AI-assisted research; verify before IC/outreach."\n    )\n\n\n    if maturity_note:\n\n        note += (\n            " "\n            + maturity_note\n        )\n\n\n    notes_cols = all_idx.get(\n        normalize_header(\n            "Extra Notes"\n        ),\n        []\n    )\n\n\n    if notes_cols:\n\n        row[\n            notes_cols[0] - 1\n        ] = note\n\n\n    if len(\n        notes_cols\n    ) >= 2:\n\n        row[\n            notes_cols[1] - 1\n        ] = (\n            f"Verification: "\n            f"{verification_reason}"\n        )\n\n\n    # ------------------------------------------------------------\n    # Updates\n    # ------------------------------------------------------------\n\n    col = get_col(\n        "Updates",\n        first_idx\n    )\n\n\n    if col:\n\n        timestamp = datetime.now(\n            timezone.utc\n        ).strftime(\n            "%Y-%m-%d %H:%M UTC"\n        )\n\n\n        row[\n            col - 1\n        ] = (\n            f"Sourced {timestamp} "\n            f"via {partner_name}."\n        )\n\n\n    return row, populated\n\n\n# ============================================================================\n# 16. WRITE + READ-BACK VERIFICATION\n# ============================================================================\n\ndef append_and_verify_row(\n    worksheet,\n    row,\n    headers,\n    company_name\n):\n\n    if len(row) != len(\n        headers\n    ):\n\n        raise RuntimeError(\n            f"Row width mismatch: "\n            f"{len(row)} cells vs "\n            f"{len(headers)} sheet columns."\n        )\n\n\n    # ------------------------------------------------------------\n    # Determine expected next row.\n    # ------------------------------------------------------------\n\n    existing_values = worksheet.get_all_values()\n\n\n    expected_row_number = (\n        len(existing_values)\n        + 1\n    )\n\n\n    print(\n        f"      Google Sheets target row: "\n        f"{expected_row_number}"\n    )\n\n\n    # ------------------------------------------------------------\n    # Show what we are about to write.\n    # ------------------------------------------------------------\n\n    nonempty = sum(\n        1\n        for value in row\n        if normalize_text(\n            value\n        )\n    )\n\n\n    print(\n        f"      Cells populated: "\n        f"{nonempty}/{len(row)}"\n    )\n\n\n    # ------------------------------------------------------------\n    # ACTUAL WRITE.\n    # ------------------------------------------------------------\n\n    worksheet.append_row(\n        row,\n        value_input_option="USER_ENTERED"\n    )\n\n\n    print(\n        "      WRITE: successful"\n    )\n\n\n    # ------------------------------------------------------------\n    # READ-BACK.\n    # ------------------------------------------------------------\n\n    time.sleep(\n        1\n    )\n\n\n    written_row = worksheet.row_values(\n        expected_row_number\n    )\n\n\n    # If concurrent edits changed the expected row,\n    # search the bottom portion for the company name.\n\n    if (\n        not written_row\n        or\n        len(written_row) == 0\n    ):\n\n        all_values = worksheet.get_all_values()\n\n\n        company_col = None\n\n\n        for i, header in enumerate(\n            headers\n        ):\n\n            if normalize_header(\n                header\n            ) == "company name":\n\n                company_col = i\n                break\n\n\n        if company_col is not None:\n\n            for row_number, candidate_row in enumerate(\n                all_values,\n                start=1\n            ):\n\n                if (\n                    len(candidate_row)\n                    > company_col\n                    and\n                    normalize_company_name(\n                        candidate_row[\n                            company_col\n                        ]\n                    )\n                    ==\n                    normalize_company_name(\n                        company_name\n                    )\n                ):\n\n                    written_row = candidate_row\n                    expected_row_number = row_number\n                    break\n\n\n    # ------------------------------------------------------------\n    # Verify Company Name.\n    # ------------------------------------------------------------\n\n    company_col = None\n\n\n    for i, header in enumerate(\n        headers\n    ):\n\n        if normalize_header(\n            header\n        ) == "company name":\n\n            company_col = i\n            break\n\n\n    if company_col is None:\n\n        raise RuntimeError(\n            "Could not find Company Name column "\n            "during write verification."\n        )\n\n\n    actual_company = ""\n\n\n    if len(\n        written_row\n    ) > company_col:\n\n        actual_company = normalize_text(\n            written_row[\n                company_col\n            ]\n        )\n\n\n    if normalize_company_name(\n        actual_company\n    ) != normalize_company_name(\n        company_name\n    ):\n\n        raise RuntimeError(\n            "READ-BACK VERIFICATION FAILED.\\n"\n            f"Expected: {company_name}\\n"\n            f"Found: {actual_company}\\n"\n            f"Row: {expected_row_number}"\n        )\n\n\n    # ------------------------------------------------------------\n    # Verify Country if present.\n    # ------------------------------------------------------------\n\n    country_col = None\n\n\n    for i, header in enumerate(\n        headers\n    ):\n\n        if normalize_header(\n            header\n        ) == "country":\n\n            country_col = i\n            break\n\n\n    actual_country = ""\n\n\n    if (\n        country_col is not None\n        and\n        len(written_row) > country_col\n    ):\n\n        actual_country = normalize_text(\n            written_row[\n                country_col\n            ]\n        )\n\n\n    print(\n        f"      READ-BACK: successful"\n    )\n\n\n    print(\n        f"      Row verified: "\n        f"{expected_row_number}"\n    )\n\n\n    print(\n        f"      Company verified: "\n        f"{actual_company}"\n    )\n\n\n    if actual_country:\n\n        print(\n            f"      Country verified: "\n            f"{actual_country}"\n        )\n\n\n    return expected_row_number\n\n\n# ============================================================================\n# 17. TARGETED HEADQUARTERS RESEARCH\n# ============================================================================\n#\n# If the first deep research returns Country/Headquarters blank,\n# we do NOT immediately reject the company.\n#\n# We run one targeted search.\n#\n# If headquarters is still unknown after that:\n#     REJECT\n#\n# ============================================================================\n\ndef enrich_geography(\n    company_name,\n    record\n):\n\n    country = normalize_country(\n        record.get(\n            "Country",\n            ""\n        )\n    )\n\n\n    headquarters = normalize_text(\n        record.get(\n            "Headquarters",\n            ""\n        )\n    )\n\n\n    if country in ELIGIBLE_COUNTRIES:\n\n        return record\n\n\n    if headquarters:\n\n        ok, detected, _ = geography_check(\n            record\n        )\n\n\n        if ok:\n\n            record[\n                "Country"\n            ] = detected\n\n            return record\n\n\n    print(\n        "      Country/headquarters not sufficiently "\n        "established — running targeted geography search..."\n    )\n\n\n    query = (\n        f\'"{company_name}" \'\n        f\'headquarters headquarters location \'\n        f\'company based in founded India Singapore \'\n        f\'Sri Lanka Bangladesh Pakistan Nepal\'\n    )\n\n\n    try:\n\n        result = tavily_search(\n            query,\n            max_results=5\n        )\n\n\n        text = combined_raw_text(\n            result,\n            char_limit=8000\n        )\n\n\n        if not text:\n\n            return record\n\n\n        prompt = f"""\nDetermine ONLY the company\'s headquarters geography.\n\nCompany:\n{company_name}\n\nResearch:\n{text}\n\nReturn ONLY valid JSON:\n\n{{\n  "Country": "",\n  "Headquarters": "",\n  "confidence": "high"\n}}\n\nRules:\n- Country must be the country where the company is headquartered.\n- Do not use founder nationality.\n- Do not use investor nationality.\n- Do not use customer geography.\n- Do not use an office/market presence unless it is the actual headquarters.\n- If uncertain, return empty strings.\n"""\n\n\n        response = robust_call_llm(\n            prompt,\n            max_tokens=500\n        )\n\n\n        enrichment = safe_json_parse(\n            response\n        )\n\n\n        if not enrichment:\n\n            return record\n\n\n        new_country = normalize_text(\n            enrichment.get(\n                "Country",\n                ""\n            )\n        )\n\n\n        new_hq = normalize_text(\n            enrichment.get(\n                "Headquarters",\n                ""\n            )\n        )\n\n\n        if new_country:\n\n            record[\n                "Country"\n            ] = new_country\n\n\n        if new_hq:\n\n            record[\n                "Headquarters"\n            ] = new_hq\n\n\n    except Exception as error:\n\n        print(\n            f"      Geography enrichment failed: "\n            f"{error}"\n        )\n\n\n    return record\n\n\n# ============================================================================\n# 18. LOAD GOOGLE SHEETS\n# ============================================================================\n\nprint("\\n" + "=" * 80)\nprint("CONNECTING TO GOOGLE SHEETS")\nprint("=" * 80)\n\n\nif "sourcing_ws" not in globals():\n\n    raise RuntimeError(\n        "sourcing_ws is not available. "\n        "Run Cell 4 before Cell 9."\n    )\n\n\nif "partner_ws" not in globals():\n\n    raise RuntimeError(\n        "partner_ws is not available. "\n        "Run Cell 4 before Cell 9."\n    )\n\n\nif "control_ws" not in globals():\n\n    raise RuntimeError(\n        "control_ws is not available. "\n        "Run Cell 4 before Cell 9."\n    )\n\n\nsourcing_headers = sourcing_ws.row_values(\n    1\n)\n\n\nif not sourcing_headers:\n\n    raise RuntimeError(\n        "Active Sourcing has no header row."\n    )\n\n\nprint(\n    f"Active Sourcing columns: "\n    f"{len(sourcing_headers)}"\n)\n\n\nif len(\n    sourcing_headers\n) != 38:\n\n    print(\n        "WARNING: Expected 38 columns based on "\n        "the current workbook."\n    )\n\n    print(\n        f"Actual columns: "\n        f"{len(sourcing_headers)}"\n    )\n\n\nprint(\n    "\\nActive Sourcing headers:"\n)\n\n\nfor i, header in enumerate(\n    sourcing_headers,\n    start=1\n):\n\n    print(\n        f"{i:2d}: {repr(header)}"\n    )\n\n\n# ============================================================================\n# 19. EXISTING COMPANY INDEX\n# ============================================================================\n\nprint("\\n" + "=" * 80)\nprint("BUILDING EXISTING COMPANY INDEX")\nprint("=" * 80)\n\n\nexisting_indexes = build_existing_indexes(\n    sourcing_ws\n)\n\n\nprint(\n    f"Existing company names: "\n    f"{len(existing_indexes[\'names\'])}"\n)\n\n\nprint(\n    f"Existing domains: "\n    f"{len(existing_indexes[\'domains\'])}"\n)\n\n\nprint(\n    f"Existing LinkedIn URLs: "\n    f"{len(existing_indexes[\'linkedin\'])}"\n)\n\n\n# ============================================================================\n# 20. LOAD PARTNERS\n# ============================================================================\n\npartners = worksheet_rows_as_dicts(\n    partner_ws\n)\n\n\nif not partners:\n\n    raise RuntimeError(\n        "No partners were found."\n    )\n\n\ncontrol_state = get_control_state(\n    control_ws\n)\n\n\npartners_to_process = choose_partners(\n    partners,\n    control_state,\n    max_partners\n)\n\n\nprint("\\n" + "=" * 80)\nprint("PARTNERS SELECTED")\nprint("=" * 80)\n\n\nfor partner in partners_to_process:\n\n    print(\n        f"  • "\n        f"{normalize_text(partner.get(\'Company Name\', \'\'))}"\n    )\n\n\n# ============================================================================\n# 21. RUN STATE\n# ============================================================================\n\nrun_started = datetime.now(\n    timezone.utc\n)\n\n\naccepted_companies = []\n\naccepted_details = []\n\nrejected_candidates = []\n\nskipped_duplicates = []\n\nfailed_partners = []\n\npartner_stats = {}\n\ndeep_research_count = 0\n\ncandidate_count = 0\n\n\n# ============================================================================\n# 22. MAIN PARTNER LOOP\n# ============================================================================\n\nfor partner in partners_to_process:\n\n    if len(\n        accepted_companies\n    ) >= target_companies:\n\n        break\n\n\n    if deep_research_count >= max_deep_research:\n\n        break\n\n\n    partner_name = normalize_text(\n        partner.get(\n            "Company Name",\n            ""\n        )\n    )\n\n\n    if not partner_name:\n\n        continue\n\n\n    print("\\n")\n    print("=" * 80)\n    print(\n        f"PARTNER: {partner_name}"\n    )\n    print("=" * 80)\n\n\n    partner_added = 0\n\n\n    try:\n\n        # ====================================================================\n        # 22A. PORTFOLIO URL\n        # ====================================================================\n\n        portfolio_url = ""\n\n\n        for field in [\n            "Company Portfolio",\n            "Portfolio",\n            "Portfolio URL",\n            "Website",\n            "Company Website",\n        ]:\n\n            value = normalize_text(\n                partner.get(\n                    field,\n                    ""\n                )\n            )\n\n\n            if value:\n\n                portfolio_url = value\n                break\n\n\n        portfolio_domain = normalize_domain(\n            portfolio_url\n        )\n\n\n        # ====================================================================\n        # 22B. PORTFOLIO SEARCH\n        # ====================================================================\n\n        if portfolio_domain:\n\n            print(\n                f"Portfolio domain: "\n                f"{portfolio_domain}"\n            )\n\n\n            portfolio_result = tavily_search(\n                "portfolio companies startups",\n                include_domains=[\n                    portfolio_domain\n                ],\n                max_results=max_tavily_results\n            )\n\n\n        else:\n\n            print(\n                "No portfolio URL found."\n            )\n\n\n            print(\n                "Using general partner portfolio search."\n            )\n\n\n            portfolio_result = tavily_search(\n                (\n                    f\'"{partner_name}" \'\n                    f\'portfolio companies startups \'\n                    f\'B2B seed India Singapore\'\n                ),\n                max_results=max_tavily_results\n            )\n\n\n        portfolio_text = combined_raw_text(\n            portfolio_result,\n            char_limit=max_research_chars\n        )\n\n\n        if not portfolio_text:\n\n            print(\n                "No usable portfolio research."\n            )\n\n\n            partner_stats[\n                partner_name\n            ] = 0\n\n\n            update_control_state(\n                control_ws,\n                partner_name,\n                0\n            )\n\n\n            continue\n\n\n        # ====================================================================\n        # 22C. CANDIDATE EXTRACTION\n        # ====================================================================\n\n        candidate_prompt = f"""\nYou are an investment sourcing analyst helping nVentures identify\nearly-stage B2B startups for Fund II.\n\nPARTNER:\n{partner_name}\n\nHARD GEOGRAPHIC REQUIREMENT:\nThe company MUST be headquartered in one of:\n\nAfghanistan\nBangladesh\nBhutan\nIndia\nMaldives\nNepal\nPakistan\nSri Lanka\nSingapore\n\nA company is NOT eligible merely because:\n- the founder is South Asian\n- the founder lives in South Asia\n- it has customers in South Asia\n- it has an office in South Asia\n- it has investors in South Asia\n\nThe company\'s actual headquarters must be in an eligible country.\n\nOTHER REQUIREMENTS:\n\n1. B2B:\n   Primarily sells to businesses, institutions or organizations.\n\n2. EARLY STAGE:\n   Prefer pre-seed or seed.\n   Exclude Series A or later.\n   Exclude clearly mature/growth companies.\n\n3. FUNDING:\n   Prefer companies with approximately $3M or less total funding.\n\n4. REAL COMPANY:\n   Must have credible evidence of an actual operating company/product.\n\nReturn ONLY valid JSON:\n\n{{\n  "candidates": [\n    {{\n      "company_name": "Company Name",\n      "sector_guess": "Sector",\n      "why_it_fits": "Short factual explanation."\n    }}\n  ]\n}}\n\nIf no suitable candidates exist:\n\n{{\n  "candidates": []\n}}\n\nWEB CONTENT:\n{portfolio_text}\n"""\n\n\n        print(\n            "Running AI candidate extraction..."\n        )\n\n\n        extraction_reply = robust_call_llm(\n            candidate_prompt,\n            max_tokens=1800\n        )\n\n\n        extraction = safe_json_parse(\n            extraction_reply\n        )\n\n\n        candidates = extraction.get(\n            "candidates",\n            []\n        )\n\n\n        if not isinstance(\n            candidates,\n            list\n        ):\n\n            candidates = []\n\n\n        candidates = candidates[\n            :max_candidates_per_partner\n        ]\n\n\n        print(\n            f"AI returned "\n            f"{len(candidates)} candidates."\n        )\n\n\n        # ====================================================================\n        # 22D. CANDIDATE LOOP\n        # ====================================================================\n\n        for candidate in candidates:\n\n            if len(\n                accepted_companies\n            ) >= target_companies:\n\n                break\n\n\n            if deep_research_count >= max_deep_research:\n\n                break\n\n\n            candidate_count += 1\n\n\n            candidate_name = normalize_text(\n                candidate.get(\n                    "company_name",\n                    ""\n                )\n            )\n\n\n            if not candidate_name:\n\n                continue\n\n\n            print("\\n" + "-" * 70)\n            print(\n                f"Candidate #{candidate_count}: "\n                f"{candidate_name}"\n            )\n\n\n            # ================================================================\n            # EARLY DUPLICATE\n            # ================================================================\n\n            if company_is_existing(\n                candidate_name,\n                indexes=existing_indexes\n            ):\n\n                print(\n                    "  SKIP — duplicate already in Google Sheets."\n                )\n\n\n                skipped_duplicates.append(\n                    candidate_name\n                )\n\n\n                continue\n\n\n            initial_context = normalize_text(\n                candidate.get(\n                    "why_it_fits",\n                    ""\n                )\n            )\n\n\n            sector_guess = normalize_text(\n                candidate.get(\n                    "sector_guess",\n                    ""\n                )\n            )\n\n\n            print(\n                f"  Sector guess: "\n                f"{sector_guess or \'unknown\'}"\n            )\n\n\n            # ================================================================\n            # DEEP RESEARCH\n            # ================================================================\n\n            deep_research_count += 1\n\n\n            time.sleep(\n                request_delay\n            )\n\n\n            research_query = (\n                f\'"{candidate_name}" \'\n                f\'company headquarters founders \'\n                f\'funding seed B2B customers investors \'\n                f\'India Singapore Sri Lanka Bangladesh \'\n                f\'Pakistan Nepal\'\n            )\n\n\n            print(\n                "  Running deep company research..."\n            )\n\n\n            deep_result = tavily_search(\n                research_query,\n                max_results=max_tavily_results\n            )\n\n\n            deep_text = combined_raw_text(\n                deep_result,\n                char_limit=max_research_chars\n            )\n\n\n            if not deep_text:\n\n                print(\n                    "  REJECT — no usable research."\n                )\n\n\n                rejected_candidates.append(\n                    (\n                        candidate_name,\n                        "No usable research"\n                    )\n                )\n\n\n                continue\n\n\n            # ================================================================\n            # STRUCTURED RESEARCH\n            # ================================================================\n\n            research_prompt = f"""\nYou are conducting structured research on a startup for an investment\npipeline.\n\nCompany:\n{candidate_name}\n\nInitial reason:\n{initial_context}\n\nUse ONLY facts supported by the supplied research.\n\nIMPORTANT:\n- Never invent facts.\n- Never guess.\n- Missing information must be "".\n- Headquarters must be the company\'s actual headquarters.\n- Country must be the country of the company\'s headquarters.\n- Founder nationality is NOT company geography.\n- Investor geography is NOT company geography.\n- Customer geography is NOT company geography.\n\nReturn ONLY valid JSON:\n\n{{\n  "Company Name": "",\n  "Country": "",\n  "Sector": "",\n  "Business Model": "",\n  "Stage": "",\n  "Founded Year": "",\n  "Headquarters": "",\n  "Website": "",\n  "Company LinkedIn": "",\n  "Company Description": "",\n  "Product Description": "",\n  "Target Market": "",\n  "Team Size": "",\n  "Number of Customers": "",\n  "Notable Customers": "",\n  "Revenue Generated": "",\n  "Unique Value Propositions": "",\n  "Competitors": "",\n  "Vision": "",\n  "Founder Name": "",\n  "Founder LinkedIn": "",\n  "Last Round": "",\n  "Notable Investors": ""\n}}\n\nRESEARCH:\n{deep_text}\n"""\n\n\n            research_reply = robust_call_llm(\n                research_prompt,\n                max_tokens=2200\n            )\n\n\n            record = safe_json_parse(\n                research_reply\n            )\n\n\n            record = clean_ai_record(\n                record\n            )\n\n\n            if not normalize_text(\n                record.get(\n                    "Company Name",\n                    ""\n                )\n            ):\n\n                record[\n                    "Company Name"\n                ] = candidate_name\n\n\n            if not normalize_text(\n                record.get(\n                    "Sector",\n                    ""\n                )\n            ):\n\n                record[\n                    "Sector"\n                ] = sector_guess\n\n\n            # ================================================================\n            # GEOGRAPHY ENRICHMENT\n            # ================================================================\n\n            record = enrich_geography(\n                candidate_name,\n                record\n            )\n\n\n            # ================================================================\n            # HARD GEOGRAPHIC FILTER\n            # ================================================================\n\n            geography_ok, detected_country, detected_hq = (\n                geography_check(\n                    record\n                )\n            )\n\n\n            if not geography_ok:\n\n                print(\n                    "  REJECTED — outside eligible geography "\n                    "or headquarters could not be verified."\n                )\n\n\n                print(\n                    f"  Country: "\n                    f"{record.get(\'Country\', \'\') or \'UNKNOWN\'}"\n                )\n\n\n                print(\n                    f"  Headquarters: "\n                    f"{record.get(\'Headquarters\', \'\') or \'UNKNOWN\'}"\n                )\n\n\n                rejected_candidates.append(\n                    (\n                        candidate_name,\n                        (\n                            "Outside eligible geography or "\n                            "headquarters unknown — "\n                            f"country: "\n                            f"{record.get(\'Country\', \'\') or \'UNKNOWN\'}"\n                        )\n                    )\n                )\n\n\n                continue\n\n\n            print(\n                f"  Geography PASS — "\n                f"{detected_country.title()}"\n            )\n\n\n            print(\n                f"  Headquarters: "\n                f"{detected_hq or \'not provided\'}"\n            )\n\n\n            # ================================================================\n            # WEBSITE / LINKEDIN\n            # ================================================================\n\n            website = normalize_text(\n                record.get(\n                    "Website",\n                    ""\n                )\n            )\n\n\n            company_linkedin = normalize_text(\n                record.get(\n                    "Company LinkedIn",\n                    ""\n                )\n            )\n\n\n            # ================================================================\n            # SECOND DUPLICATE CHECK\n            # ================================================================\n\n            researched_name = normalize_text(\n                record.get(\n                    "Company Name",\n                    ""\n                )\n            ) or candidate_name\n\n\n            if company_is_existing(\n                researched_name,\n                website=website,\n                linkedin=company_linkedin,\n                indexes=existing_indexes\n            ):\n\n                print(\n                    "  SKIP — duplicate after research."\n                )\n\n\n                skipped_duplicates.append(\n                    researched_name\n                )\n\n\n                continue\n\n\n            # ================================================================\n            # DETERMINISTIC FUNDING / MATURITY FILTER\n            # ================================================================\n\n            funding_ok, funding_reason = funding_check(\n                record,\n                deep_text\n            )\n\n\n            if not funding_ok:\n\n                print(\n                    "  REJECTED — funding/maturity."\n                )\n\n\n                print(\n                    f"  {funding_reason}"\n                )\n\n\n                rejected_candidates.append(\n                    (\n                        researched_name,\n                        funding_reason\n                    )\n                )\n\n\n                continue\n\n\n            # ================================================================\n            # VERIFICATION\n            # ================================================================\n\n            verification_prompt = f"""\nYou are the final screening analyst for an early-stage VC sourcing\npipeline.\n\nCompany:\n{researched_name}\n\nResearch:\n{deep_text}\n\nEvaluate ONLY using the supplied research.\n\nReturn ONLY valid JSON:\n\n{{\n  "b2b": true,\n  "early_stage": true,\n  "funding_within_limit": true,\n  "active_company": true,\n  "too_mature": false,\n  "confidence": "high",\n  "reason": "Short factual explanation"\n}}\n\nRules:\n\nB2B:\nThe company must primarily sell to businesses/institutions.\n\nEARLY STAGE:\nPre-seed or seed is preferred.\nSeries A or later = false.\nClearly mature/growth company = false.\n\nFUNDING:\nApproximately $3M total funding or less = true.\nClearly above $3M = false.\n\nACTIVE:\nThere should be evidence of an actual operating company.\n\nDo NOT treat missing evidence as positive evidence.\n\nConfidence:\n"high", "medium", or "low".\n"""\n\n\n            print(\n                "  Running final qualification..."\n            )\n\n\n            verification_reply = robust_call_llm(\n                verification_prompt,\n                max_tokens=900\n            )\n\n\n            verification = safe_json_parse(\n                verification_reply\n            )\n\n\n            b2b = (\n                verification.get(\n                    "b2b",\n                    False\n                )\n                is True\n            )\n\n\n            early_stage = (\n                verification.get(\n                    "early_stage",\n                    False\n                )\n                is True\n            )\n\n\n            funding_within_limit = (\n                verification.get(\n                    "funding_within_limit",\n                    False\n                )\n                is True\n            )\n\n\n            active_company = (\n                verification.get(\n                    "active_company",\n                    False\n                )\n                is True\n            )\n\n\n            too_mature = (\n                verification.get(\n                    "too_mature",\n                    True\n                )\n                is True\n            )\n\n\n            confidence = normalize_text(\n                verification.get(\n                    "confidence",\n                    ""\n                )\n            ).lower()\n\n\n            verification_reason = normalize_text(\n                verification.get(\n                    "reason",\n                    ""\n                )\n            )\n\n\n            failures = []\n\n\n            if globals().get(\n                "REQUIRE_B2B",\n                True\n            ) and not b2b:\n\n                failures.append(\n                    "B2B requirement not verified"\n                )\n\n\n            if globals().get(\n                "REQUIRE_EARLY_STAGE",\n                True\n            ) and not early_stage:\n\n                failures.append(\n                    "Early-stage requirement not verified"\n                )\n\n\n            if not funding_within_limit:\n\n                failures.append(\n                    "Funding requirement not satisfied"\n                )\n\n\n            if not active_company:\n\n                failures.append(\n                    "Active-company status not verified"\n                )\n\n\n            if too_mature:\n\n                failures.append(\n                    "Company appears too mature"\n                )\n\n\n            if confidence == "low":\n\n                failures.append(\n                    "Verification confidence is low"\n                )\n\n\n            if failures:\n\n                print(\n                    "  REJECTED"\n                )\n\n\n                for failure in failures:\n\n                    print(\n                        f"    - {failure}"\n                    )\n\n\n                rejected_candidates.append(\n                    (\n                        researched_name,\n                        "; ".join(\n                            failures\n                        )\n                    )\n                )\n\n\n                continue\n\n\n            # ================================================================\n            # MATURITY WARNING\n            # ================================================================\n\n            maturity_note = maturity_flag(\n                record,\n                deep_text\n            )\n\n\n            # ================================================================\n            # ACCEPT\n            # ================================================================\n\n            print(\n                f"  ACCEPTED — "\n                f"{researched_name}"\n            )\n\n\n            print(\n                f"  Country: "\n                f"{record.get(\'Country\', \'\')}"\n            )\n\n\n            print(\n                f"  Headquarters: "\n                f"{record.get(\'Headquarters\', \'\')}"\n            )\n\n\n            if maturity_note:\n\n                print(\n                    f"  WARNING: "\n                    f"{maturity_note}"\n                )\n\n\n            # ================================================================\n            # BUILD ROW\n            # ================================================================\n\n            row, populated_fields = build_sheet_row(\n                sourcing_headers,\n                record,\n                partner_name,\n                verification,\n                maturity_note\n            )\n\n\n            # ================================================================\n            # FINAL ROW VALIDATION\n            # ================================================================\n\n            if len(row) != len(\n                sourcing_headers\n            ):\n\n                raise RuntimeError(\n                    f"Row width mismatch for "\n                    f"{researched_name}: "\n                    f"{len(row)} vs "\n                    f"{len(sourcing_headers)}"\n                )\n\n\n            # ================================================================\n            # IMMEDIATE GOOGLE SHEETS WRITE\n            #\n            # This is deliberately done HERE.\n            #\n            # We no longer collect rows and wait until the very end.\n            # ================================================================\n\n            print(\n                "  Writing company to Google Sheets..."\n            )\n\n\n            written_row_number = append_and_verify_row(\n                sourcing_ws,\n                row,\n                sourcing_headers,\n                researched_name\n            )\n\n\n            print(\n                f"  ✓ CONFIRMED IN GOOGLE SHEETS"\n            )\n\n\n            print(\n                f"  ✓ Row number: "\n                f"{written_row_number}"\n            )\n\n\n            # ================================================================\n            # UPDATE IN-MEMORY DEDUPLICATION\n            # ================================================================\n\n            add_company_to_indexes(\n                researched_name,\n                website=website,\n                linkedin=company_linkedin,\n                indexes=existing_indexes\n            )\n\n\n            # ================================================================\n            # RECORD ACCEPTED COMPANY\n            # ================================================================\n\n            accepted_companies.append(\n                researched_name\n            )\n\n\n            accepted_details.append(\n                {\n                    "company":\n                        researched_name,\n\n                    "country":\n                        record.get(\n                            "Country",\n                            ""\n                        ),\n\n                    "headquarters":\n                        record.get(\n                            "Headquarters",\n                            ""\n                        ),\n\n                    "sector":\n                        record.get(\n                            "Sector",\n                            ""\n                        ),\n\n                    "stage":\n                        record.get(\n                            "Stage",\n                            ""\n                        ),\n\n                    "partner":\n                        partner_name,\n\n                    "row":\n                        written_row_number,\n\n                    "fields":\n                        len(\n                            populated_fields\n                        ),\n                }\n            )\n\n\n            partner_added += 1\n\n\n            # ================================================================\n            # CONTROL UPDATE AFTER SUCCESSFUL WRITE\n            # ================================================================\n\n            try:\n\n                update_control_state(\n                    control_ws,\n                    partner_name,\n                    partner_added\n                )\n\n            except Exception as control_error:\n\n                print(\n                    f"  Warning: control update failed: "\n                    f"{control_error}"\n                )\n\n\n            # ================================================================\n            # TARGET CHECK\n            # ================================================================\n\n            if len(\n                accepted_companies\n            ) >= target_companies:\n\n                print(\n                    "\\nTARGET REACHED."\n                )\n\n                break\n\n\n            time.sleep(\n                request_delay\n            )\n\n\n        # ====================================================================\n        # PARTNER COMPLETE\n        # ====================================================================\n\n        partner_stats[\n            partner_name\n        ] = partner_added\n\n\n        print(\n            f"\\nPartner complete: "\n            f"{partner_name}"\n        )\n\n\n        print(\n            f"New companies added: "\n            f"{partner_added}"\n        )\n\n\n        # Update control even if zero.\n        try:\n\n            update_control_state(\n                control_ws,\n                partner_name,\n                partner_added\n            )\n\n        except Exception as control_error:\n\n            print(\n                f"Warning: control update failed: "\n                f"{control_error}"\n            )\n\n\n    except Exception as partner_error:\n\n        print(\n            "\\n!! PARTNER ERROR"\n        )\n\n\n        print(\n            f"Partner: "\n            f"{partner_name}"\n        )\n\n\n        print(\n            f"Error: "\n            f"{partner_error}"\n        )\n\n\n        failed_partners.append(\n            (\n                partner_name,\n                str(partner_error)\n            )\n        )\n\n\n        # Do not kill the entire sourcing run.\n        continue\n\n\n# ============================================================================\n# 23. FINAL REPORT\n# ============================================================================\n\nrun_finished = datetime.now(\n    timezone.utc\n)\n\n\nruntime_seconds = (\n    run_finished - run_started\n).total_seconds()\n\n\nprint("\\n")\nprint("=" * 80)\nprint("FINAL SOURCING RUN REPORT")\nprint("=" * 80)\n\n\nprint(\n    f"Started: "\n    f"{run_started.strftime(\'%Y-%m-%d %H:%M:%S UTC\')}"\n)\n\n\nprint(\n    f"Finished: "\n    f"{run_finished.strftime(\'%Y-%m-%d %H:%M:%S UTC\')}"\n)\n\n\nprint(\n    f"Runtime: "\n    f"{runtime_seconds / 60:.1f} minutes"\n)\n\n\nprint(\n    f"\\nTarget companies: "\n    f"{target_companies}"\n)\n\n\nprint(\n    f"New companies added: "\n    f"{len(accepted_companies)}"\n)\n\n\nprint(\n    f"Duplicates skipped: "\n    f"{len(skipped_duplicates)}"\n)\n\n\nprint(\n    f"Candidates rejected: "\n    f"{len(rejected_candidates)}"\n)\n\n\nprint(\n    f"Deep research calls: "\n    f"{deep_research_count}"\n)\n\n\nprint(\n    f"Partners processed: "\n    f"{len(partner_stats)}"\n)\n\n\nprint(\n    f"Partner errors: "\n    f"{len(failed_partners)}"\n)\n\n\n# ============================================================================\n# 24. PARTNER BREAKDOWN\n# ============================================================================\n\nprint("\\n" + "-" * 80)\nprint("PARTNER BREAKDOWN")\nprint("-" * 80)\n\n\nif partner_stats:\n\n    for name, count in partner_stats.items():\n\n        print(\n            f"{name}: "\n            f"{count} new"\n        )\n\nelse:\n\n    print(\n        "None."\n    )\n\n\n# ============================================================================\n# 25. ACCEPTED COMPANIES\n# ============================================================================\n\nprint("\\n" + "-" * 80)\nprint("ACCEPTED COMPANIES")\nprint("-" * 80)\n\n\nif accepted_details:\n\n    for item in accepted_details:\n\n        print(\n            f"{item[\'company\']} | "\n            f"{item[\'country\']} | "\n            f"{item[\'sector\']} | "\n            f"{item[\'stage\']} | "\n            f"Row {item[\'row\']} | "\n            f"{item[\'fields\']} fields | "\n            f"{item[\'partner\']}"\n        )\n\nelse:\n\n    print(\n        "None."\n    )\n\n\n# ============================================================================\n# 26. REJECTED CANDIDATES\n# ============================================================================\n\nprint("\\n" + "-" * 80)\nprint("REJECTED CANDIDATES")\nprint("-" * 80)\n\n\nif rejected_candidates:\n\n    for name, reason in rejected_candidates:\n\n        print(\n            f"{name} -> {reason}"\n        )\n\nelse:\n\n    print(\n        "None."\n    )\n\n\n# ============================================================================\n# 27. DUPLICATES\n# ============================================================================\n\nprint("\\n" + "-" * 80)\nprint("DUPLICATES SKIPPED")\nprint("-" * 80)\n\n\nif skipped_duplicates:\n\n    for name in skipped_duplicates:\n\n        print(\n            name\n        )\n\nelse:\n\n    print(\n        "None."\n    )\n\n\n# ============================================================================\n# 28. PARTNER ERRORS\n# ============================================================================\n\nif failed_partners:\n\n    print("\\n" + "-" * 80)\n    print("PARTNER ERRORS")\n    print("-" * 80)\n\n\n    for name, error in failed_partners:\n\n        print(\n            f"{name}:"\n        )\n\n        print(\n            f"  {error}"\n        )\n\n\n# ============================================================================\n# 29. GEOGRAPHIC FILTER REPORT\n# ============================================================================\n\nprint("\\n" + "-" * 80)\nprint("HARD GEOGRAPHIC FILTER")\nprint("-" * 80)\n\n\nprint(\n    "Eligible headquarters:"\n)\n\n\nfor country in sorted(\n    ELIGIBLE_COUNTRIES\n):\n\n    print(\n        f"  ✓ {country.title()}"\n    )\n\n\nprint(\n    "\\nCompanies headquartered outside these "\n    "countries cannot be accepted."\n)\n\n\n# ============================================================================\n# 30. GOOGLE SHEETS WRITE STATUS\n# ============================================================================\n\nprint("\\n" + "-" * 80)\nprint("GOOGLE SHEETS WRITE STATUS")\nprint("-" * 80)\n\n\nif accepted_details:\n\n    print(\n        "Every accepted company was written immediately "\n        "and read-back verified."\n    )\n\n\n    for item in accepted_details:\n\n        print(\n            f"  ✓ {item[\'company\']} "\n            f"→ Active Sourcing row {item[\'row\']}"\n        )\n\nelse:\n\n    print(\n        "No accepted companies were written."\n    )\n\n\n# ============================================================================\n# 31. TARGET STATUS\n# ============================================================================\n\nprint("\\n" + "=" * 80)\n\n\nif len(\n    accepted_companies\n) >= target_companies:\n\n    print(\n        f"TARGET HIT — "\n        f"{len(accepted_companies)}/{target_companies}"\n    )\n\nelse:\n\n    print(\n        f"TARGET NOT FULLY REACHED — "\n        f"{len(accepted_companies)}/{target_companies}"\n    )\n\n\n    print(\n        "The system will not force unsuitable companies "\n        "through the filters."\n    )\n\n\nprint("=" * 80)\nprint("SOURCING RUN COMPLETE")\nprint("=" * 80)'


def run_sourcing(
    *,
    sourcing_ws,
    partner_ws,
    control_ws,
    openrouter_api_key,
    tavily_api_key,
    openrouter_model="minimax/minimax-m3:free",
    target_companies=25,
    max_partners=12,
    max_candidates_per_partner=10,
    max_deep_research=45,
    max_total_funding=3_000_000,
    max_team_size_warning=30,
    tavily_timeout=60,
    openrouter_timeout=90,
    max_tavily_results=5,
    max_research_chars=14000,
    request_delay=1.0,
    progress_callback=None,
):
    """Run the existing sourcing engine and return a structured report."""

    if not openrouter_api_key:
        raise RuntimeError("OPENROUTER_API_KEY is missing.")
    if not tavily_api_key:
        raise RuntimeError("TAVILY_API_KEY is missing.")

    # Exact Active Sourcing header row used by the existing engine.
    sourcing_headers = sourcing_ws.row_values(1)
    sourcing_first_idx = {}
    sourcing_all_idx = {}

    # The notebook engine expects these variables to exist.
    try:
        import gspread
    except ImportError as exc:
        raise RuntimeError("gspread is required.") from exc

    # Normalize header helpers are defined by the engine itself, so the
    # namespace initially gets the worksheet/config objects only.
    ns = {
        "sourcing_ws": sourcing_ws,
        "partner_ws": partner_ws,
        "control_ws": control_ws,
        "sourcing_headers": sourcing_headers,
        "OPENROUTER_API_KEY": openrouter_api_key,
        "TAVILY_API_KEY": tavily_api_key,
        "OPENROUTER_MODEL": openrouter_model,
        "TARGET_NEW_COMPANIES": int(target_companies),
        "MAX_PARTNERS_PER_RUN": int(max_partners),
        "MAX_CANDIDATES_PER_PARTNER": int(max_candidates_per_partner),
        "MAX_DEEP_RESEARCH_PER_RUN": int(max_deep_research),
        "MAX_TOTAL_FUNDING_USD": float(max_total_funding),
        "MAX_TEAM_SIZE_WARNING": int(max_team_size_warning),
        "TAVILY_TIMEOUT": int(tavily_timeout),
        "OPENROUTER_TIMEOUT": int(openrouter_timeout),
        "MAX_TAVILY_RESULTS": int(max_tavily_results),
        "MAX_RESEARCH_CHARS": int(max_research_chars),
        "REQUEST_DELAY_SECONDS": float(request_delay),
        "ELIGIBLE_COUNTRIES": ELIGIBLE_COUNTRIES,
        "progress_callback": progress_callback,
    }

    # Cell 9 is a top-level notebook program. Running it in its own namespace
    # preserves the exact tested logic while making it callable by Streamlit.
    exec(compile(ENGINE_SOURCE, "<nVentures sourcing engine>", "exec"), ns, ns)

    accepted = ns.get("accepted_companies", [])
    rejected = ns.get("rejected_candidates", [])
    # The engine's actual variable names are skipped_duplicates and
    # failed_partners. The previous wrapper looked for different names,
    # causing run history to under-report duplicates and partner errors.
    duplicates = ns.get("skipped_duplicates", [])
    partner_errors = ns.get("failed_partners", [])
    accepted_details = ns.get("accepted_details", [])

    run_started = ns.get("run_started")
    if hasattr(run_started, "isoformat"):
        started_at = run_started.isoformat()
    else:
        started_at = datetime.now(timezone.utc).isoformat()

    partner_stats = ns.get("partner_stats", {})

    return {
        "started_at": started_at,
        "finished_at": datetime.now(timezone.utc).isoformat(),
        "target": int(target_companies),
        "accepted": accepted,
        "accepted_details": accepted_details,
        "rejected": rejected,
        "duplicates": duplicates,
        "partner_errors": partner_errors,
        "deep_research_calls": ns.get(
            "deep_research_count",
            ns.get("deep_research_calls", 0),
        ),
        "partners_processed": len(partner_stats),
        "partner_breakdown": partner_stats,
        "raw_namespace": ns,
    }
